def eval_rpn(tokens):
    stack = []
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        i += 1
        if tok in ("+", "-", "*"):
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            else:
                stack.append(left * right)
        else:
            stack.append(int(tok))
    return stack.pop()

