def pair_with_sum_sorted(nums, target):
    i, j = 0, len(nums) - 1
    while i < j:
        s = nums[i] + nums[j]
        if s == target:
            return (nums[i], nums[j])
        if s < target:
            i += 1
        else:
            j -= 1
    return None

