def primes_until(limit):
    primes = []
    n = 2
    while n <= limit:
        d = 2
        is_prime = True
        while d * d <= n:
            if n % d == 0:
                is_prime = False
                break
            d += 1
        if is_prime:
            primes.append(n)
        n += 1
    return primes

