def robot(commands):
    moves = {"U": (0, 1), "D": (0, -1), "L": (-1, 0), "R": (1, 0)}
    x = y = steps = 0
    while steps < len(commands):
        dx, dy = moves[commands[steps]]
        x, y = x + dx, y + dy
        steps += 1
        if (x, y) == (0, 0):
            break
    return (x, y), steps

