def sqrt_approx(n, eps=1e-9):
    if n == 0:
        return 0
    x = n
    while abs(x * x - n) > eps:
        x = (x + n / x) / 2
    return x

def halving_steps(value, limit):
    steps = 0
    while value >= limit:
        value /= 2
        steps += 1
    return steps

