exercises.solution:
def run_until(values, stop_value, max_steps):
    i = 0
    while True:
        if i >= max_steps:
            return "limit", max_steps
        if i >= len(values):
            return "end", len(values)
        if values[i] == stop_value:
            return "found", i
        i += 1

